package scope

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func write(t *testing.T, root, rel, body string) string {
	t.Helper()
	p := filepath.Join(root, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	return p
}

func classify(t *testing.T, root, rel, body string) Verdict {
	t.Helper()
	p := write(t, root, rel, body)
	return ClassifyFile(p, rel, int64(len(body)))
}

// minifiedBody is a bundle: a banner and one very long line.
func minifiedBody() string {
	return "/*! bundle */\n!function(){" + strings.Repeat("a=b(c,d);", 300) + "}();\n"
}

// ordinary is hand-written source: short lines, plenty of them.
func ordinary() string {
	var b strings.Builder
	for i := 0; i < 120; i++ {
		b.WriteString("function f" + strings.Repeat("x", i%7) + "(a, b) { return a + b; }\n")
	}
	return b.String()
}

// Decision D6' (the heart of redteam3-d6-04): a name is not evidence.
func TestANameAloneIsNeverEvidence(t *testing.T) {
	root := t.TempDir()
	for _, tc := range []struct{ rel, body, what string }{
		{"routes.min.js", ordinary(), "ordinary source called *.min.js"},
		{"web/app.min.css", "a{b:c}\n" + ordinary(), "ordinary css called *.min.css"},
		{"package-lock.json", `{"name": "not a lockfile"}`, "a package-lock.json that is not a lockfile"},
		{"yarn.lock", "just some notes\n", "a yarn.lock that is not one"},
		{"go.sum", "this is not a go.sum\n", "a go.sum that is not one"},
		{"bundle.js.map", "not a source map", "a .map that is not a source map"},
		{"vendor/app/routes.js", ordinary(), "code under vendor/"},
	} {
		if v := classify(t, root, tc.rel, tc.body); !v.None() {
			t.Errorf("%s: classified %q; a name is not evidence, so it is in scope", tc.what, v.Reason)
		}
	}
}

func TestLockfilesAreRecognisedByNameAndFormat(t *testing.T) {
	root := t.TempDir()
	for _, tc := range []struct{ rel, body string }{
		{"package-lock.json", `{"name":"x","lockfileVersion":3,"packages":{}}`},
		{"web/npm-shrinkwrap.json", `{"lockfileVersion":1}`},
		{"yarn.lock", "# yarn lockfile v1\n\nleft-pad@^1.0.0:\n  version \"1.3.0\"\n"},
		{"berry/yarn.lock", "__metadata:\n  version: 6\n"},
		{"pnpm-lock.yaml", "lockfileVersion: '6.0'\n"},
		{"poetry.lock", "# This file is automatically @generated by Poetry 1.7 and should not be changed by hand.\n"},
		{"Cargo.lock", "# This file is automatically @generated by Cargo.\nversion = 3\n"},
		{"go.sum", "golang.org/x/mod v0.1.0 h1:abc+def=\ngolang.org/x/mod v0.1.0/go.mod h1:abc+def=\n"},
		{"composer.lock", `{"_readme":["x"],"content-hash":"abc","packages":[]}`},
		{"Gemfile.lock", "GEM\n  remote: https://rubygems.org/\n  specs:\n\nBUNDLED WITH\n   2.4.0\n"},
		{"Pipfile.lock", `{"_meta":{"hash":{}},"default":{},"develop":{}}`},
	} {
		if v := classify(t, root, tc.rel, tc.body); v.Reason != ReasonLockfile {
			t.Errorf("%s: classified %q; want a lockfile", tc.rel, v.Reason)
		}
	}
}

func TestSourceMapNeedsTheVersionAndMappings(t *testing.T) {
	root := t.TempDir()
	if v := classify(t, root, "app.js.map", `{"version":3,"file":"app.js","sources":["a.ts"],"mappings":"AAAA"}`); v.Reason != ReasonSourceMap {
		t.Errorf("a version-3 source map classified %q", v.Reason)
	}
	for _, body := range []string{`{"version":2,"mappings":"AAAA"}`, `{"version":3}`, `[]`, `{"version":3,"mappings":7}`} {
		if v := classify(t, root, "x.js.map", body); !v.None() {
			t.Errorf("%s classified %q", body, v.Reason)
		}
	}
}

// The thresholds were measured on real minified and first-party files; these
// are the shapes.
func TestMinifiedIsMeasuredFromTheContent(t *testing.T) {
	root := t.TempDir()
	for _, tc := range []struct {
		rel, body string
		want      Reason
	}{
		{"static/bundle.js", minifiedBody(), ReasonMinified}, // no "min" in the name
		{"a.min.js", minifiedBody(), ReasonMinified},
		{"style.css", "a{" + strings.Repeat("color:red;", 200) + "}\n", ReasonMinified},
		{"ok.js", ordinary(), ""},
		// One giant base64 line among hundreds of code lines: the ordinary lines
		// keep the file in scope.
		{"logo.ts", "const logo = \"" + strings.Repeat("QUJD", 5000) + "\";\n" + ordinary(), ""},
		// Too small to say anything.
		{"tiny.js", "a=1;b=2;\n", ""},
		// Prose with long lines is not minified.
		{"docs.tsx", strings.Repeat("This is a long documentation sentence that goes on and on. "+strings.Repeat("word ", 40)+"\n", 30), ""},
	} {
		if v := classify(t, root, tc.rel, tc.body); v.Reason != tc.want {
			t.Errorf("%s: classified %q, want %q", tc.rel, v.Reason, tc.want)
		}
	}
}

func TestMinifiedAndVendoredFilesAreTheOnesExcludableUnderTheCap(t *testing.T) {
	for r, want := range map[Reason]bool{
		ReasonMinified: true, ReasonVendored: true,
		ReasonGenerated: false, ReasonCompiled: false, ReasonLockfile: false, ReasonSourceMap: false,
	} {
		if got := (Verdict{r}).ExcludableUnderCap(); got != want {
			t.Errorf("ExcludableUnderCap(%q) = %v, want %v", r, got, want)
		}
	}
}

// libraryBody is the body of a library of the given size: lines that use its
// identifier, as the real file does.
func libraryBody(ident string, size int) string {
	var b strings.Builder
	for i := 0; b.Len() < size; i++ {
		b.WriteString("function " + ident + "_helper" + strings.Repeat("x", i%7) + "(a, b) { return " + ident + ".fn(a, b); }\n")
	}
	return b.String()
}

func TestVendoredLibrariesAreRecognisedByTheirBannerAndBody(t *testing.T) {
	root := t.TempDir()
	for _, tc := range []struct{ name, banner, ident string }{
		{"jquery", "/*! jQuery v3.6.0 | (c) OpenJS Foundation and other contributors | jquery.org/license */\n", "jQuery"},
		{"jquery-ui", "/*! jQuery UI - v1.12.1 - 2016-09-14\n* Copyright jQuery Foundation and other contributors; Licensed MIT */\n", "jQuery"},
		{"bootstrap", "/*!\n * Bootstrap v3.1.1 (http://getbootstrap.com)\n * Copyright 2011-2014 Twitter, Inc.\n * Licensed under MIT\n */\n", "bootstrap"},
		{"underscore", "//     Underscore.js 1.10.2\n//     https://underscorejs.org\n//     (c) 2009-2020 Jeremy Ashkenas\n", "underscore"},
		{"lodash", "/**\n * @license\n * Lodash <https://lodash.com/>\n * Copyright OpenJS Foundation\n */\n", "lodash"},
		{"react", "/** @license React v17.0.2\n * react.production.min.js\n * Copyright (c) Facebook, Inc.\n * MIT license */\n", "React"},
		{"three", "/**\n * @license\n * Copyright 2010-2022 Three.js Authors\n * SPDX-License-Identifier: MIT\n */\n", "THREE"},
		{"three-old", "/**\n * @author mrdoob / http://mrdoob.com/\n */\n", "THREE"},
		{"ace", "/* ***** BEGIN LICENSE BLOCK *****\n * Distributed under the BSD license:\n * Copyright (c) 2010, Ajax.org B.V.\n */\n", "ace"},
		{"pdfjs", "/**\n * @licstart The following is the entire license notice for the\n * JavaScript code in this page\n * Copyright 2024 Mozilla Foundation\n */\n", "pdf"},
	} {
		if v := classify(t, root, tc.name+".js", tc.banner+libraryBody(tc.ident, 12<<10)); v.Reason != ReasonVendored {
			t.Errorf("%s: classified %q; want a vendored library", tc.name, v.Reason)
		}
	}
}

// redteam4-d6-01 and DE4-01: a banner that only mentions a library, a /*!
// banner of any name, and a body that is not the library are not evidence. Each
// of these fixtures was classified vendored (and so left out of Semgrep, with
// the scan reading complete) before the library had to be identified.
func TestAFirstPartyFileThatMentionsALibraryIsNotThatLibrary(t *testing.T) {
	root := t.TempDir()
	body := libraryBody("jQuery", 12<<10)
	for _, tc := range []struct{ name, file string }{
		{"spdx-mention", "// SPDX-License-Identifier: MIT\n// Copyright (c) 2026 Acme Corp\n// Realtime chat routes that sit next to our Socket.IO server.\n" + body},
		{"lodash-credit", "// Copyright (c) 2024 Acme Inc. All rights reserved. built on lodash 4.17.\n" + body},
		{"chartjs-mention", "/* Dashboard rendered with Chart.js. Version 1.2 (c) 2024 Acme */\n" + body},
		{"socketio-version", "// Socket.IO chat handlers. Copyright 2024 Acme. v2.0\n" + body},
		{"own-project-bang", "/*! acme-portal v2.3.1 | (c) 2026 Acme Corp | MIT License */\n" + body},
		{"any-bang", "/*! some-lib v2.4.1 | MIT License | (c) Someone */\n" + body},
		{"mention-after-name", "/*! my-jquery-wrapper v3.6.0 | jQuery helpers | (c) Acme | MIT */\n" + body},
		{"jquery-plugin-by-someone", "/*! jQuery Plugin: Are-You-Sure v1.9.0 | (c) Chris Dance | MIT */\n" + body},
	} {
		if v := classify(t, root, tc.name+".js", tc.file); !v.None() {
			t.Errorf("%s: classified %q; a mention is not identification, so it is in scope", tc.name, v.Reason)
		}
	}
	for _, tc := range []struct{ name, file string }{
		// The banner names jQuery but the body is not jQuery.
		{"banner-only", "/*! jQuery v3.6.0 | (c) OpenJS Foundation | jquery.org/license */\n" + ordinary() + strings.Repeat("// padding\n", 1200)},
		// Too small to be a library.
		{"tiny", "/*! jQuery v3.6.0 | (c) OpenJS Foundation | jquery.org/license */\njQuery.fn.a = jQuery.fn.b = jQuery.fn.c = 1;\n"},
		// A real banner and a body that handles an HTTP request.
		{"app-with-banner", "/*! jQuery v3.6.0 | (c) OpenJS Foundation | jquery.org/license */\n" + body + "app.get('/u', (req, res) => db.query('SELECT ' + req.query.id));\n"},
		{"late-banner", "const a = jQuery;\n/*! jQuery v3.6.0 | (c) OpenJS Foundation */\n" + body},
	} {
		if v := classify(t, root, tc.name+".js", tc.file); !v.None() {
			t.Errorf("%s: classified %q; want in scope", tc.name, v.Reason)
		}
	}
}

func TestGeneratorHeaders(t *testing.T) {
	root := t.TempDir()
	for _, tc := range []struct{ rel, body string }{
		{"api/user.pb.go", "// Code generated by protoc-gen-go. DO NOT EDIT.\n// source: user.proto\n\npackage api\n"},
		{"gen.go", "// Code generated by stringer; DO NOT EDIT.\n\npackage x\n"},
		{"user_pb2.py", "# -*- coding: utf-8 -*-\n# Generated by the protocol buffer compiler.  DO NOT EDIT!\n# source: user.proto\n"},
		{"types.ts", "/* eslint-disable */\n// @generated by protoc-gen-ts\n"},
		{"a.js", "// @generated\nmodule.exports = {};\n"},
		{"thrift.py", "#\n# Autogenerated by Thrift Compiler (0.19.0)\n#\n# DO NOT EDIT UNLESS YOU ARE SURE THAT YOU KNOW WHAT YOU ARE DOING\n"},
		{"Api.java", "/**\n * NOTE: This class is auto generated by the swagger code generator program.\n * Do not edit the class manually.\n */\n"},
		{"models.py", "# Generated by Django 4.2.7 on 2023-11-01 10:00\n\nfrom django.db import migrations\n"},
		{"gen.rb", "# This file is automatically generated. Do not edit.\n"},
	} {
		if v := classify(t, root, tc.rel, tc.body); v.Reason != ReasonGenerated {
			t.Errorf("%s: classified %q; want a generator header", tc.rel, v.Reason)
		}
	}
	for _, tc := range []struct{ rel, body string }{
		{"hand.go", "package x\n\n// generated is a variable name here\nvar generated = 1\n"},
		{"note.py", "x = 'DO NOT EDIT this generated string'\n"},
		{"late.go", strings.Repeat("// filler\n", 40) + "// Code generated by x. DO NOT EDIT.\npackage x\n"},
		{"code.js", "const msg = \"@generated\";\n"},
	} {
		if v := classify(t, root, tc.rel, tc.body); !v.None() {
			t.Errorf("%s: classified %q; want in scope", tc.rel, v.Reason)
		}
	}
}

func TestCompiledOutputHasASourceMapReferenceOrABundlerBootstrap(t *testing.T) {
	root := t.TempDir()
	if v := classify(t, root, "dist/app.js", ordinary()+"//# sourceMappingURL=app.js.map\n"); v.Reason != ReasonCompiled {
		t.Errorf("a trailing sourceMappingURL classified %q", v.Reason)
	}
	if v := classify(t, root, "dist/main.js", "/******/ (() => { // webpackBootstrap\n"+ordinary()); v.Reason != ReasonCompiled {
		t.Errorf("a webpack bootstrap classified %q", v.Reason)
	}
	if v := classify(t, root, "dist/plain.js", ordinary()); !v.None() {
		t.Errorf("a plain file under dist/ classified %q", v.Reason)
	}
}

func TestBinaryContentCarriesNoEvidence(t *testing.T) {
	root := t.TempDir()
	if v := classify(t, root, "blob.js", "// @generated\x00\x00\x00\n"); !v.None() {
		t.Errorf("a file with NUL bytes classified %q; the analyzers record it themselves", v.Reason)
	}
}

func TestDirectoriesNeedMarkersNotNames(t *testing.T) {
	root := t.TempDir()
	for _, rel := range []string{"node_modules", "vendor", "dist", "build", "target", ".next", ".venv", "venv", ".npm", "site-packages"} {
		write(t, root, rel+"/app.js", "run();\n")
		if v := ClassifyDir(filepath.Join(root, rel), rel); !v.None() {
			t.Errorf("%s/ with only code in it classified %q; a name is not evidence", rel, v.Reason)
		}
	}
	for _, tc := range []struct {
		dir  string
		file map[string]string
		want Reason
	}{
		{"node_modules", map[string]string{".package-lock.json": `{"lockfileVersion": 3}`}, ReasonNPMInstall},
		{"web/node_modules", map[string]string{".yarn-integrity": "{}"}, ReasonNPMInstall},
		{"vendor", map[string]string{"modules.txt": "# github.com/a/b v1.2.3\n## explicit; go 1.20\n"}, ReasonGoVendor},
		{"vendor", map[string]string{"autoload.php": "<?php", "composer/installed.json": `{"packages": []}`}, ReasonComposer},
		{"target", map[string]string{"CACHEDIR.TAG": "Signature: 8a477f597d28d172789f06886806bc55\n"}, ReasonCargoTarget},
		{".next", map[string]string{"BUILD_ID": "x", "build-manifest.json": "{}"}, ReasonNextBuild},
		{".npm", map[string]string{"_cacache/index-v5/x": "x"}, ReasonNPMCache},
		{"anything", map[string]string{"pyvenv.cfg": "home = /usr/bin\ninclude-system-site-packages = false\n"}, ReasonPythonVenv},
		{"env", map[string]string{"conda-meta/history": ""}, ReasonPythonVenv},
		{"lib/site-packages", map[string]string{"requests-2.0.dist-info/METADATA": "x", "requests-2.0.dist-info/RECORD": "x"}, ReasonPythonInstall},
	} {
		r := t.TempDir()
		for rel, body := range tc.file {
			write(t, r, tc.dir+"/"+rel, body)
		}
		if v := ClassifyDir(filepath.Join(r, filepath.FromSlash(tc.dir)), tc.dir); v.Reason != tc.want {
			t.Errorf("%s with %v classified %q, want %q", tc.dir, keys(tc.file), v.Reason, tc.want)
		}
	}
	// A pyvenv.cfg that does not name a home is not a virtualenv's.
	r := t.TempDir()
	write(t, r, "x/pyvenv.cfg", "nothing useful\n")
	if v := ClassifyDir(filepath.Join(r, "x"), "x"); !v.None() {
		t.Errorf("a pyvenv.cfg without home classified %q", v.Reason)
	}
}

func TestMavenAndGradleBuildDirectoriesNeedTheirProject(t *testing.T) {
	r := t.TempDir()
	write(t, r, "pom.xml", "<project/>")
	write(t, r, "target/maven-status/x", "x")
	if v := ClassifyDir(filepath.Join(r, "target"), "target"); v.Reason != ReasonMavenTarget {
		t.Errorf("maven target classified %q", v.Reason)
	}
	r = t.TempDir()
	write(t, r, "target/maven-status/x", "x") // no pom.xml beside it
	if v := ClassifyDir(filepath.Join(r, "target"), "target"); !v.None() {
		t.Errorf("target/ without a pom.xml classified %q", v.Reason)
	}
	r = t.TempDir()
	write(t, r, "build.gradle", "")
	write(t, r, "build/classes/x", "x")
	if v := ClassifyDir(filepath.Join(r, "build"), "build"); v.Reason != ReasonGradleBuild {
		t.Errorf("gradle build classified %q", v.Reason)
	}
	r = t.TempDir()
	write(t, r, "setup.py", "")
	write(t, r, "build/lib/x.py", "x")
	write(t, r, "build/bdist.linux-x86_64/x", "x")
	if v := ClassifyDir(filepath.Join(r, "build"), "build"); v.Reason != ReasonSetuptools {
		t.Errorf("setuptools build classified %q", v.Reason)
	}
}

func TestAnInstalledNpmPackageIsRecognisedByItsPackageJSON(t *testing.T) {
	r := t.TempDir()
	write(t, r, "node_modules/left-pad/package.json", `{"name":"left-pad","version":"1.3.0"}`)
	write(t, r, "node_modules/@scope/pkg/package.json", `{"name":"@scope/pkg","version":"2.0.0"}`)
	write(t, r, "node_modules/liar/package.json", `{"name":"something-else","version":"1.0.0"}`)
	write(t, r, "node_modules/noversion/package.json", `{"name":"noversion"}`)
	for rel, want := range map[string]Reason{
		"node_modules/left-pad": ReasonNPMInstall, "node_modules/@scope/pkg": ReasonNPMInstall,
		"node_modules/liar": "", "node_modules/noversion": "",
	} {
		if v := ClassifyDir(filepath.Join(r, filepath.FromSlash(rel)), rel); v.Reason != want {
			t.Errorf("%s classified %q, want %q", rel, v.Reason, want)
		}
	}
}

func keys(m map[string]string) []string {
	var out []string
	for k := range m {
		out = append(out, k)
	}
	return out
}
